"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";
import Link from "next/link";
import { Logo } from "@/components/Logo";
import { LoginForm } from "@/components/LoginForm";

// Vervang je bestaande LoginPage-component door dit bestand.
// Zowel een named als default export is beschikbaar voor je huidige imports.
// Logo en LoginForm blijven bestaan: de inloglogica wordt niet vervangen.

// ---------- Routes en API-koppeling ----------
const LOGIN_URL = "/login"; // Zet op "/" als jullie login op de homepage staat.
const REGISTRATIE_URL = "/registreren";
// Vul hier pas jullie bestaande registratie-endpoint in.
// Zonder endpoint worden geen wachtwoorden verstuurd of accounts nagebootst.
const REGISTRATIE_ENDPOINT: string | null = null;

function RegistratieForm() {
  const [zichtbaar, setZichtbaar] = useState(false);
  const [bezig, setBezig] = useState(false);
  const [fout, setFout] = useState("");
  const [klaar, setKlaar] = useState(false);
  const verzoek = useRef<AbortController | null>(null);

  useEffect(() => () => verzoek.current?.abort(), []);

  async function registreren(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (bezig) return;
    const form = event.currentTarget;
    const data = new FormData(form);
    const naam = String(data.get("naam") ?? "").trim();
    const gebruikersnaam = String(data.get("gebruikersnaam") ?? "").trim();
    const email = String(data.get("email") ?? "").trim();
    const wachtwoord = String(data.get("wachtwoord") ?? "");
    setFout("");
    if (!naam || !gebruikersnaam || !email || !wachtwoord) {
      setFout("Vul alle velden in.");
      return;
    }
    if (wachtwoord !== data.get("herhaling")) {
      setFout("De wachtwoorden komen niet overeen.");
      return;
    }
    if (!REGISTRATIE_ENDPOINT) {
      setFout(
        "Registreren is nog niet beschikbaar. De registratie moet nog worden gekoppeld.",
      );
      return;
    }
    setBezig(true);
    const controller = new AbortController();
    verzoek.current = controller;
    try {
      // Pas veldnamen aan op jullie API. De server moet zelf ook valideren.
      const antwoord = await fetch(REGISTRATIE_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        signal: controller.signal,
        body: JSON.stringify({ naam, gebruikersnaam, email, wachtwoord }),
      });
      // Contract: de API stuurt { success: true } zodra het account is aangemaakt.
      const resultaat: unknown = await antwoord.json().catch(() => null);
      if (
        !antwoord.ok ||
        !resultaat ||
        typeof resultaat !== "object" ||
        !("success" in resultaat) ||
        resultaat.success !== true
      ) {
        setFout("Registreren is niet gelukt. Controleer je gegevens en probeer opnieuw.");
        return;
      }
      form.reset();
      setKlaar(true);
    } catch {
      if (!controller.signal.aborted) setFout("Geen verbinding. Probeer het opnieuw.");
    } finally {
      if (!controller.signal.aborted) setBezig(false);
    }
  }

  if (klaar)
    return (
      <div role="status" className="habico-registratie-klaar">
        <p>Je account is aangemaakt. Je kunt nu inloggen.</p>
        <Link href={LOGIN_URL}>Naar inloggen →</Link>
      </div>
    );

  return (
    <form onSubmit={registreren} className="habico-registratie-form">
      <label htmlFor="signup-email">
        E-mailadres
        <input
          id="signup-email"
          name="email"
          type="email"
          autoComplete="email"
          required
          maxLength={254}
          placeholder="jij@voorbeeld.nl"
        />
      </label>
      <div className="habico-form-rij">
        <label htmlFor="signup-naam">
          Volledige naam
          <input
            id="signup-naam"
            name="naam"
            autoComplete="name"
            required
            maxLength={100}
            placeholder="Jouw naam"
          />
        </label>
        <label htmlFor="signup-gebruiker">
          Gebruikersnaam
          <input
            id="signup-gebruiker"
            name="gebruikersnaam"
            autoComplete="username"
            required
            minLength={3}
            maxLength={40}
            placeholder="Kies een naam"
          />
        </label>
      </div>
      <label htmlFor="signup-wachtwoord">
        Wachtwoord
        <span className="habico-wachtwoordveld">
          <input
            id="signup-wachtwoord"
            name="wachtwoord"
            type={zichtbaar ? "text" : "password"}
            autoComplete="new-password"
            required
            minLength={12}
            aria-describedby="signup-hulp"
            placeholder="Kies een wachtwoord"
          />
          <button
            type="button"
            className="habico-toon"
            aria-controls="signup-wachtwoord signup-herhaling"
            aria-pressed={zichtbaar}
            onClick={() => setZichtbaar(!zichtbaar)}
          >
            {zichtbaar ? "Verberg" : "Toon"}
          </button>
        </span>
      </label>
      <p id="signup-hulp" className="habico-form-hulp">
        Gebruik minimaal 12 tekens.
      </p>
      <label htmlFor="signup-herhaling">
        Herhaal wachtwoord
        <input
          id="signup-herhaling"
          name="herhaling"
          type={zichtbaar ? "text" : "password"}
          autoComplete="new-password"
          required
          minLength={12}
          placeholder="Nog een keer je wachtwoord"
        />
      </label>
      {fout && (
        <p role="alert" className="habico-form-fout">
          {fout}
        </p>
      )}
      <button type="submit" disabled={bezig}>
        {bezig ? "Account aanmaken…" : "Account aanmaken"}
      </button>
    </form>
  );
}

// De kaarten beschrijven functies; dit zijn geen verzonnen gebruikersreviews.
const kaarten = [
  { nummer: "01", titel: "Een eerlijk verdeeld huis.", tekst: "Van de keuken tot de badkamer. Zie wie wat doet en houd samen jullie huis op orde.", label: "Schoonmaaktaken", icoon: "✳" },
  { nummer: "02", titel: "Nooit meer iets vergeten.", tekst: "Eén boodschappenlijst voor het hele huis. Voeg toe wat op is en vink af wat je meeneemt.", label: "Boodschappen", icoon: "+" },
  { nummer: "03", titel: "Meer tijd voor samen.", tekst: "Een huisavond, een afspraak of een etentje. Jullie plannen overzichtelijk op één plek.", label: "Gezamenlijke agenda", icoon: "↗" },
  { nummer: "04", titel: "Iedereen op de hoogte.", tekst: "Alle huisgenoten verbonden. Minder losse berichtjes, meer overzicht in jullie studentenhuis.", label: "Huisgenoten", icoon: "⌂" },
];

function AuthPage({ registratie }: { registratie: boolean }) {
  return (
    <main className="habico-login">
      <aside className="habico-verhaal" aria-label="Samen wonen met Habico">
        <div className="habico-gradient" aria-hidden="true"><i /><i /><i /></div>
        {/* Ingebedde transparante mascotte: geen extra afbeeldingsbestand nodig. */}
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img className="habico-mascotte" src="data:image/png;base64," alt="" aria-hidden="true" draggable={false} />
        <div className="habico-brand"><Logo /></div>
        <div className="habico-intro">
          <h2>Samen wonen.<br />Samen geregeld.</h2>
          <p>Een fijn huis begint met overzicht. Regel je taken, boodschappen en plannen samen met Habico.</p>
        </div>
        <div className="habico-marquee">
          <div className="habico-track">
            {[0, 1].map((kopie) => (
              <div className="habico-kaartgroep" key={kopie} aria-hidden={kopie === 1 ? true : undefined}>
                {kaarten.map((kaart) => (
                  <article className="habico-feature" key={kaart.nummer}>
                    <span className="habico-kaartnummer">{kaart.nummer} / SAMEN THUIS</span>
                    <h3>{kaart.titel}</h3>
                    <p>{kaart.tekst}</p>
                    <div className="habico-kaartvoet"><span>{kaart.label}<small>Alles op één plek</small></span><span className="habico-feature-icoon" aria-hidden="true">{kaart.icoon}</span></div>
                  </article>
                ))}
              </div>
            ))}
          </div>
        </div>
        <div className="habico-samen"><span>Een fijn huis doe je samen</span><div><span>Taken</span><span>Boodschappen</span><span>Agenda</span></div></div>
      </aside>
      <section className="habico-formulierpaneel" aria-labelledby="habico-login-titel">
        <div className="habico-mobile-logo"><Logo /></div>
        <div className="habico-auth-card">
          <header className="habico-formulierkop">
            <h1 id="habico-login-titel">{registratie ? "Maak je account" : "Welkom terug"}</h1>
            <p>{registratie ? "Een fijn huis begint met samen." : "Log in en kijk wat er speelt in jouw huis."}</p>
          </header>
          {/* Bestaande authenticatie en validatie blijven in LoginForm. */}
          <div className="habico-login-velden">{registratie ? <RegistratieForm /> : <LoginForm />}</div>
          <p className="habico-wisselen">{registratie ? "Heb je al een account?" : "Nog geen account?"}{" "}<Link href={registratie ? LOGIN_URL : REGISTRATIE_URL}>{registratie ? "Inloggen" : "Account aanmaken"}</Link></p>
        </div>
      </section>
    </main>
  );
}
export function LoginPage() { return <AuthPage registratie={false} />; }
export function SignupPage() { return <AuthPage registratie />; }
export default LoginPage;
